import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`resume-builder`,heroTitle:`Build your perfect resume in minutes`,heroSubtitle:`Perplexity Computer pulls your LinkedIn, crafts an ATS-friendly resume, and optimizes it for every new job posting automatically.`,inputUrlCta:`Build my resume`,inputUrlPlaceholder:`linkedin.com/in/yourname`,inputUrlPrefill:`Go to {url} and extract all profile information from this LinkedIn page, including work experience, education, skills, certifications, and summary. Then ask me what target role I'm pursuing, what industry I'm focused on, and any specific achievements I want to highlight. Once I respond: 1) Analyze my LinkedIn profile against ATS resume best practices for the target role. 2) Research top job postings for that role to identify the most common required keywords, skills, and qualifications. 3) Construct a fully formatted ATS-friendly resume with optimized section headers, quantified achievements, keyword-rich bullet points, and a tailored professional summary. 4) Score the resume's ATS compatibility against the top five current job postings for my target role. 5) Identify any gaps between my experience and common job requirements, with suggestions to address them. 6) Build a reusable system that takes any new job posting URL and automatically tailors my resume by adjusting keywords, reordering bullet points, and customizing the summary to match that posting. Deliver the final resume in a clean, copy-ready format plus a gap analysis and the job-posting optimization workflow.`,heroOverlaySteps:[`Extracting your experience, skills, and achievements from LinkedIn`,`Researching target role requirements and ATS keyword patterns`,`Constructing your ATS-optimized resume with tailored bullet points`,`Resume, gap analysis, and job-posting optimizer ready to use`],generatingSteps:[`Visiting {url} to extract your full professional profile and career history`,`Designing an agent to research target role keywords and ATS requirements`,`Configuring resume construction with optimized formatting, metrics, and keyword placement`,`Setting up your job-posting optimization system for one-click resume tailoring`],featureSectionTitle:`From LinkedIn to interview-ready resume`,featureCardTitles:[`Connects to your career tools`,`Outputs you can submit`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Google Drive, Google Sheets, and Notion plug into one workflow so your resume moves from draft to application without manual copy-paste.`,`ATS-optimized resume. Keyword gap analysis. Role-specific compatibility scores. A reusable system that tailors your resume to any new job posting.`],capabilitySectionTitle:`Your career coach, on autopilot`,capabilitySectionSubtitle:`Paste your LinkedIn, describe your target role, and get back a tailored resume plus an optimization system.`,capabilityCards:[{title:`Profile Extraction`,description:`Computer can pull every detail from your LinkedIn, from work history and skills to certifications and education, and structure it for a professional resume.`},{title:`ATS Optimization`,description:`Computer can analyze job postings for your target role, extract the keywords and qualifications ATS systems scan for, and weave them into your resume.`},{title:`Resume Construction`,description:`Computer can build a polished resume with quantified achievements, action-verb bullet points, and a tailored summary formatted to pass ATS filters.`},{title:`Connect Your Tools`,description:`Computer can export to Google Docs, Google Drive, Notion, and Google Sheets so your job search workflow stays in one place.`},{title:`Remember & Improve`,description:`Computer can remember your experience, target roles, and past resume versions across sessions so every iteration builds on what works.`},{title:`New Posting Alerts`,description:`Computer can monitor job boards for new postings matching your target role and generate a tailored resume version for each one.`}]});export{t as default};
